/**
 * Built-in policy profiles for common repository types.
 *
 * Profiles only set requirements that are relevant to their ecosystem —
 * a documentation-only repository is never asked to run unit tests.
 */

export type ProfileId = 'minimal' | 'node' | 'python' | 'go' | 'rust' | 'docs';

export interface Profile {
  id: ProfileId;
  title: string;
  description: string;
  /** Policy YAML with {{PROJECT_NAME}} placeholders. */
  template: string;
}

const header = `# ContribSpec contribution policy
# Generated by "contribspec init". Validate with: contribspec validate
# Schema: https://contribspec.dev/schema/contribspec-policy-v1.json
version: 1
`;

