export const PROFILE_IDS: ProfileId[] = ['minimal', 'node', 'python', 'go', 'rust', 'docs'];

/** Renders a profile template with the project name substituted. */
export function renderProfile(id: ProfileId, projectName: string): string {
  const profile = PROFILES[id];
  const safeName = projectName.replace(/[\r\n"\\]/g, '').slice(0, 100) || 'my-project';
  return profile.template.replaceAll('{{PROJECT_NAME}}', safeName);
}
